rows.vgi.example_queries:
[
  {
    "description": "Look up the meaning and DFIR relevance of a single Windows event id.",
    "sql": "SELECT name, dfir_use FROM evtx.main.windows_event_id_reference WHERE event_id = 4688"
  },
  {
    "description": "List the curated Security-channel event ids in numeric order.",
    "sql": "SELECT event_id, name FROM evtx.main.windows_event_id_reference WHERE channel = 'Security' ORDER BY event_id"
  },
  {
    "description": "Hunt failed logons and lockouts: select the event ids from the reference by name, then pull the targeted account and source IP address out of each matching record's event_json.",
    "sql": "SELECT r.record_id, r.time_created, ref.name, r.event_json->>'$.Event.EventData.TargetUserName' AS target_user, r.event_json->>'$.Event.EventData.IpAddress' AS source_ip FROM evtx.main.evtx_records('test/sql/data/sample-security.evtx') AS r JOIN evtx.main.windows_event_id_reference AS ref ON ref.event_id = r.event_id AND ref.channel = r.channel WHERE ref.name IN ('Failed logon', 'Account locked out') ORDER BY r.time_created, r.record_id;"
  }
]
